        for (int i = 0; i < candidates.size(); ++i) {
            auto p = candidates[i];
            char last = p.second;
            if (i < candidates.size() - 1) {
                auto next = candidates[i+1];
                char first = next.second;
                if (last == 'k' && first == 'n') {
                    cross_pairs++;
                }
            }
        }
        int total_letters = 0;
        for (auto &p : candidates) {
            total_letters += m;
        }
        int result = max(10 * (sum_s + cross_pairs) - total_letters, 0);
        cout << result << endl;
    }
    return 0;
}
